  bool selectBFP16_ADDMAC_CONF(MachineInstr &I, MachineRegisterInfo &MRI,
                               unsigned Opcode);
  bool selectCascadeStreamInsn(MachineInstr &I, MachineRegisterInfo &MRI,
                               bool IsWrite);

private:
