// Selector for BFP mul/negmul intrinsics (24 operands + conf)
bool AIE2PSInstructionSelector::selectBFP16_MUL_CONF(MachineInstr &I,
                                                     MachineRegisterInfo &MRI,
                                                     unsigned Opcode) {
  // Result register
  const Register DstReg = I.getOperand(0).getReg();

  // Operand 1 is intrinsic ID, operands start at 2
  // First operand (mEXv): 3 components
  const Register X1 = I.getOperand(2).getReg(); // VEC512
  const Register T1 = I.getOperand(3).getReg(); // mGGs
  const Register E1 = I.getOperand(4).getReg(); // mEEs

  // Second operand (eEY): 12 components
  const Register X21 = I.getOperand(5).getReg();  // VEC512
  const Register X22 = I.getOperand(6).getReg();  // VEC512
  const Register X23 = I.getOperand(7).getReg();  // VEC512
  const Register X24 = I.getOperand(8).getReg();  // VEC512
  const Register T21 = I.getOperand(9).getReg();  // mGGs
  const Register T22 = I.getOperand(10).getReg(); // mGGs
  const Register T23 = I.getOperand(11).getReg(); // mGGs
  const Register T24 = I.getOperand(12).getReg(); // mGGs
  const Register E21 = I.getOperand(13).getReg(); // mEEs
  const Register E22 = I.getOperand(14).getReg(); // mEEs
  const Register E23 = I.getOperand(15).getReg(); // mEEs
  const Register E24 = I.getOperand(16).getReg(); // mEEs

  // Config register
  const Register Conf = I.getOperand(17).getReg(); // mRv8

  // Build composite registers using REG_SEQUENCE
  const Register Operand1 = buildBFP320(X1, T1, E1, /*low*/ true, MRI);
  const Register Operand2 = buildBFP1280(X21, T21, E21, X22, T22, E22, MRI);
  const Register Operand3 = buildBFP1280(X23, T23, E23, X24, T24, E24, MRI);
  const Register Operand4 = buildBFP320(X1, T1, E1, /*low*/ false, MRI);

  // Build the instruction
  auto MI = MIB.buildInstr(Opcode, {DstReg},
                           {Operand1, Operand2, Operand3, Operand4, Conf});

  I.eraseFromParent();
  return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
}

