bool AIE2PSInstructionSelector::canCombineUPS(MachineInstr &LoadOp,
                                              MachineInstr &UPSI,
                                              MachineRegisterInfo &MRI) {
  Register LoadResult = (std::next(UPSI.uses().begin()))->getReg();
  if (LoadOp.getParent() != UPSI.getParent() || !MRI.hasOneUse(LoadResult)) {
    return false;
  }
  const std::optional<APInt> NoImmediate = {};
  const bool IsSigned = true;
  return getCombinedOpcodeUPS(LoadOp, UPSI, NoImmediate, IsSigned).has_value();
}

bool AIE2PSInstructionSelector::selectG_AIE_LOAD_UPS(
    MachineInstr &UPSI, MachineRegisterInfo &MRI,
    std::optional<unsigned> crUPSModeVal) {
  // First use is the G_INTRINSIC_W_SIDE_EFFECTS ID
  Register LoadResult = (std::next(UPSI.uses().begin()))->getReg();
  MachineInstr *LoadOp = getDefIgnoringCopiesAndBitcasts(LoadResult, MRI);
  MachineInstr *InsertionPoint = &UPSI;

  assert(LoadOp && "Expected SSA.");

  // Do not try to combine if one of the load's defs is used by another
  // instruction between the load and the VUPS or if there is a store
  // between the load and the VUPS.
  if (!canDelayMemOp(*LoadOp, UPSI, MRI)) {
    // If we cannot delay the load, we can try to advance the combined
    // instruction to the load's position.
    if (canAdvanceOp(*LoadOp, UPSI, MRI, /*SideEffectsAreChecked=*/true))
      InsertionPoint = LoadOp;
    else
      return false;
  }

  if (!canCombineUPS(*LoadOp, UPSI, MRI))
    return false;

  assert(getLoadStoreSize(*LoadOp) == 256 || getLoadStoreSize(*LoadOp) == 512);

  std::optional<AddressingModeInfo> AMI =
      getOrDefineAddressingRegister(*LoadOp, MRI);
  if (!AMI)
    return false;

  Register DstReg = UPSI.getOperand(0).getReg();
  // In this case of G_INTRINSIC_W_SIDE_EFFECTS operand 1 is target intrinsic
  // In this case the operand 2 is the source register which is the loaded value
  Register ShftReg = UPSI.getOperand(3).getReg();
  Register SignReg = UPSI.getOperand(4).getReg();

  auto SignVal = getIConstantVRegValWithLookThrough(SignReg, MRI);
  bool ConstantSign = SignVal ? true : false;
  // SignVal = 1 for signed and 0 for dynamically signed
  std::optional<LoadStoreOpcodes> LSO =
      getCombinedOpcodeUPS(*LoadOp, UPSI, AMI->ImmediateOffset,
                           ConstantSign ? SignVal.value().Value == 0x1 : false);

  assert(LSO && "Unexpected VLDA.UPS combine failure");

  unsigned MemOpLoadStoreSize = getLoadStoreSize(*LoadOp);
  TypeSize DstRegSize = MRI.getType(DstReg).getSizeInBits();
  assert(((MemOpLoadStoreSize == 256 &&
           (DstRegSize != 512 || DstRegSize != 1024)) ||
          (MemOpLoadStoreSize == 512 &&
           (DstRegSize != 1024 || DstRegSize != 2048))) &&
         "Unexpected VLDA.UPS size");

  if (!crUPSModeVal.has_value())
    return false;
  // Selects the mode of the accumulator for UPS instructions
  // 0 – 32-bit accumulator lane
  // 1 – 64-bit accumulator lane
  MIB.setInstr(*InsertionPoint);
  setCtrlRegister(MIB, AIE2PS::crUPSMode, *crUPSModeVal);

  auto NewInstr = MIB.buildInstr(LSO->ISelOpcode);

  NewInstr.addDef(DstReg);
  // Skip first def, which is the value directly fed into the UPS unit
  for (auto *Def = std::next(LoadOp->defs().begin());
       Def != LoadOp->defs().end(); ++Def)
    NewInstr.addDef(Def->getReg());

  NewInstr.addUse(ShftReg);

  addAddressingMode(NewInstr, *AMI, LSO->FitsImmediateRange, false, MRI);

  NewInstr.cloneMemRefs(*LoadOp);

  if (!ConstantSign)
    setUnsetCtrlRegister(MIB, *NewInstr, MRI, AIE2PS::upsSign0, SignReg);

  UPSI.eraseFromParent();
  makeDeadMI(*LoadOp, MRI);
  return constrainSelectedInstRegOperands(*NewInstr.getInstr(), TII, TRI, RBI);
}

bool AIE2PSInstructionSelector::selectWideG_AIE_LOAD_STORE(
    MachineInstr &I, LoadStoreOpcodes &LSO, AddressingModeInfo &AMI,
    MachineRegisterInfo &MRI) {
  LLT SrcDstTy = MRI.getType(AMI.SrcDstOp.getReg());
  const unsigned SrcDstTySize = SrcDstTy.getSizeInBits();
  const unsigned SplitFactor = (SrcDstTySize == 1024) ? 2 : 4;
  const unsigned OpIdx = AMI.MemI.mayStore() ? I.getNumExplicitDefs() : 0;
  const unsigned RBID = deriveRegBankID(I.getOperand(OpIdx).getReg(), MRI, RBI);
  const TargetRegisterClass *RC512 = nullptr;
  const TargetRegisterClass *RC1024 = nullptr;
  const TargetRegisterClass *RC2048 = &AIE2PS::ACC2048RegClass;
  SmallVector<unsigned, 4> SubRegIdxes;

  if (RBID == AIE2PS::AccRegBankID) {
    SubRegIdxes = {AIE2PS::sub_512_acc_lo, AIE2PS::sub_512_acc_hi,
                   AIE2PS::sub_1024_acc_hi_then_sub_512_acc_lo,
                   AIE2PS::sub_1024_acc_hi_then_sub_512_acc_hi};
    RC512 = &AIE2PS::ACC512RegClass;
    RC1024 = &AIE2PS::ACC1024RegClass;
  } else if (RBID == AIE2PS::VRegBankID) {
    SubRegIdxes = {AIE2PS::sub_512_lo, AIE2PS::sub_512_hi};
    RC512 = &AIE2PS::VEC512RegClass;
    RC1024 = &AIE2PS::VEC1024RegClass;
  } else {
    llvm_unreachable("Unknown Register Bank ID!");
  }
  std::vector<Register> SubRegs(SplitFactor);
  for (unsigned I = 0; I < SplitFactor; ++I) {
    SubRegs[I] = MRI.createVirtualRegister(RC512);
  }

  auto handleSplitMemOperands = [&](auto &Instrs) {
    if (SrcDstTySize == 1024) {
      addSplitMemOperands(AMI.MemI, Instrs[1], Instrs[0], 0, 2);
    } else { // SrcDstTySize == 2048
      addSplitMemOperands(AMI.MemI, Instrs[3], Instrs[2], 128, 4);
      addSplitMemOperands(AMI.MemI, Instrs[1], Instrs[0], 0, 4);
    }
  };

  auto constrainInstRegOps = [&](auto &Instrs) {
    return std::all_of(Instrs.begin(), Instrs.end(), [&](const auto &Instr) {
      return constrainSelectedInstRegOperands(*Instr, TII, TRI, RBI);
    });
  };

  SmallVector<MachineInstrBuilder, 4> SplitInstrs;
  switch (AMI.MemI.getOpcode()) {
  case AIE2PS::G_STORE:
  case AIE2PS::G_AIE_POSTINC_STORE:
  case AIE2PS::G_AIE_POSTINC_2D_STORE:
  case AIE2PS::G_AIE_POSTINC_3D_STORE: {
    // Split Offsets first and then perform the postinc.
    // For consistency, also handle G_STORE in the same manner.
    for (int SubRegIdx = SplitFactor - 1; SubRegIdx >= 0; SubRegIdx--) {
      const unsigned Offset = SubRegIdx * 64;
      auto Copy = MIB.buildInstr(TargetOpcode::COPY, {SubRegs[SubRegIdx]}, {})
                      .addReg(AMI.SrcDstOp.getReg(), 0,
                              SubRegIdxes[SubRegIdx % SubRegIdxes.size()]);
      MachineInstrBuilder StoreInstr;
      if (SubRegIdx == 0) {
        StoreInstr = MIB.buildInstr(LSO.ISelOpcode, {}, {});
        for (auto Def : AMI.MemI.defs())
          StoreInstr.addDef(Def.getReg());
        StoreInstr.addReg(Copy.getReg(0));
        addAddressingMode(StoreInstr, AMI, LSO.FitsImmediateRange, false, MRI);
      } else {

        StoreInstr = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                         .addReg(Copy.getReg(0))
                         .addReg(AMI.PtrOp.getReg())
                         .addImm(Offset);
      }
      SplitInstrs.push_back(StoreInstr);
    }
    handleSplitMemOperands(SplitInstrs);
    break;
  }
  case AIE2PS::G_AIE_OFFSET_STORE: {
    if (!LSO.FitsImmediateRange) {
      // Emit an PTR_ADD to evaluate the offset
      insertPtrAddForOffset(MRI, AMI.MemI);
    }
    for (unsigned SubRegIdx = 0; SubRegIdx < SplitFactor; ++SubRegIdx) {
      const unsigned Offset = SubRegIdx * 64;
      auto Copy = MIB.buildInstr(TargetOpcode::COPY, {SubRegs[SubRegIdx]}, {})
                      .addReg(AMI.SrcDstOp.getReg(), 0,
                              SubRegIdxes[SubRegIdx % SubRegIdxes.size()]);
      MachineInstrBuilder StoreInstr;
      if (SubRegIdx == 0) {
        StoreInstr = MIB.buildInstr(LSO.ISelOpcode, {}, {});
        StoreInstr.addReg(Copy.getReg(0));

        StoreInstr.addUse(AMI.PtrOp.getReg());

        if (LSO.FitsImmediateRange) {
          StoreInstr.addImm(AMI.ImmediateOffset->getSExtValue()); // Offset
        } else {
          // In this case we have already inserted a PTR_ADD to add the offset
          // to the base pointer
          StoreInstr.addImm(0); // Offset
        }
      } else { // SubRegIdx != 0
        if (LSO.FitsImmediateRange) {
          StoreInstr = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                           .addReg(Copy.getReg(0))
                           .addReg(AMI.PtrOp.getReg())
                           .addImm(AMI.ImmediateOffset->getSExtValue() +
                                   Offset); // Offset
        } else {
          StoreInstr = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                           .addReg(Copy.getReg(0))
                           .addReg(AMI.PtrOp.getReg())
                           .addImm(Offset); // Offset
        }
      }
      SplitInstrs.push_back(StoreInstr);
    }
    handleSplitMemOperands(SplitInstrs);
    break;
  }
  case AIE2PS::G_LOAD:
  case AIE2PS::G_AIE_POSTINC_LOAD:
  case AIE2PS::G_AIE_POSTINC_2D_LOAD:
  case AIE2PS::G_AIE_POSTINC_3D_LOAD: {
    // Split Offsets first and then perform the postinc.
    // For consistency, also handle G_LOAD in the same manner.
    for (int SubRegIdx = SplitFactor - 1; SubRegIdx >= 0; SubRegIdx--) {
      MachineInstrBuilder Load;
      if (SubRegIdx == 0) {
        Load = MIB.buildInstr(LSO.ISelOpcode, {SubRegs[0]}, {});
        for (auto *Def = AMI.MemI.defs().begin() + 1;
             Def != AMI.MemI.defs().end(); Def++) {
          Load.addDef(Def->getReg());
        }
        addAddressingMode(Load, AMI, LSO.FitsImmediateRange, false, MRI);
      } else {
        Load = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                   .addDef(SubRegs[SubRegIdx])
                   .addUse(AMI.PtrOp.getReg())
                   .addImm(SubRegIdx * 64);
      }
      SplitInstrs.push_back(Load);
    }
    auto RegSeq =
        MIB.buildInstr(AIE2PS::REG_SEQUENCE, {AMI.SrcDstOp.getReg()}, {});
    for (unsigned SubRegIdx = 0; SubRegIdx < SplitFactor; ++SubRegIdx) {
      RegSeq.addReg(SubRegs[SubRegIdx]).addImm(SubRegIdxes[SubRegIdx]);
    }
    const Register SrcDstReg = AMI.SrcDstOp.getReg();
    if (!RBI.constrainGenericRegister(
            SrcDstReg, *(SrcDstTySize == 2048 ? RC2048 : RC1024), MRI))
      return false;

    handleSplitMemOperands(SplitInstrs);
    break;
  }
  case AIE2PS::G_AIE_OFFSET_LOAD: {
    if (!LSO.FitsImmediateRange) {
      // Emit an PTR_ADD to evaluate the offset
      insertPtrAddForOffset(MRI, AMI.MemI);
    }
    for (unsigned SubRegIdx = 0; SubRegIdx < SplitFactor; ++SubRegIdx) {
      MachineInstrBuilder Load;
      if (SubRegIdx == 0) {
        Load = MIB.buildInstr(LSO.ISelOpcode, {SubRegs[0]}, {})
                   .addUse(AMI.PtrOp.getReg());
        if (LSO.FitsImmediateRange) {
          Load.addImm(AMI.ImmediateOffset->getSExtValue()); // Offset
        } else {
          // In this case we have already inserted a PTR_ADD to add the offset
          // to the base pointer
          Load.addImm(0); // Offset
        }
      } else { // SubRegIdx != 0
        if (LSO.FitsImmediateRange) {
          Load = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                     .addDef(SubRegs[SubRegIdx])
                     .addUse(AMI.PtrOp.getReg())
                     .addImm(AMI.ImmediateOffset->getSExtValue() +
                             SubRegIdx * 64); // Offset
        } else {
          Load = MIB.buildInstr(*LSO.OffsetOpcode, {}, {})
                     .addDef(SubRegs[SubRegIdx])
                     .addUse(AMI.PtrOp.getReg())
                     .addImm(SubRegIdx * 64); // Offset
        }
      }
      SplitInstrs.push_back(Load);
    }
    auto RegSeq =
        MIB.buildInstr(AIE2PS::REG_SEQUENCE, {AMI.SrcDstOp.getReg()}, {});
    for (unsigned SubRegIdx = 0; SubRegIdx < SplitFactor; ++SubRegIdx) {
      RegSeq.addReg(SubRegs[SubRegIdx]).addImm(SubRegIdxes[SubRegIdx]);
    }
    const Register SrcDstReg = AMI.SrcDstOp.getReg();
    if (!RBI.constrainGenericRegister(
            SrcDstReg, *(SrcDstTySize == 2048 ? RC2048 : RC1024), MRI))
      return false;

    handleSplitMemOperands(SplitInstrs);
    break;
  }
  default:
    return false;
  }

  AMI.MemI.eraseFromParent();
  return constrainInstRegOps(SplitInstrs);
}

static unsigned int getStoreFifoOpcode(MachineInstr &I) {
  switch (cast<GIntrinsic>(I).getIntrinsicID()) {
  case Intrinsic::aie2ps_fifo_st_flush:
    return AIE2PS::VST_FLUSH_normal_flush;
  case Intrinsic::aie2ps_fifo_st_flush_1d:
    return AIE2PS::VST_FLUSH_fifo_1d_flush;
  case Intrinsic::aie2ps_fifo_st_flush_2d:
    return AIE2PS::VST_FLUSH_2D;
  case Intrinsic::aie2ps_fifo_st_flush_3d:
    return AIE2PS::VST_FLUSH_3D;
  case Intrinsic::aie2ps_fifo_st_flush_conv:
    return AIE2PS::VST_FLUSH_d_normal_flush;
  case Intrinsic::aie2ps_fifo_st_flush_1d_conv:
    return AIE2PS::VST_FLUSH_d_fifo_1d_flush;
  case Intrinsic::aie2ps_fifo_st_flush_2d_conv:
    return AIE2PS::VST_FLUSH_d_2D;
  case Intrinsic::aie2ps_fifo_st_flush_3d_conv:
    return AIE2PS::VST_FLUSH_d_3D;
  case Intrinsic::aie2ps_fifo_st_push_512:
    return AIE2PS::VST_PUSH_512_dmx_sts_fifo_bare_x;
  case Intrinsic::aie2ps_fifo_st_push_BFP384:
    return AIE2PS::VST_PUSH_384;
  case Intrinsic::aie2ps_fifo_st_push_BFP640:
    return AIE2PS::VST_PUSH_576;
  case Intrinsic::aie2ps_fifo_st_push_BFP768:
    return AIE2PS::VST_PUSH_768;
  }
  llvm_unreachable("Unreachable: Cannot get fifo store opcode from intrinsic");
  return AIE2PS::INSTRUCTION_LIST_END;
}

bool AIE2PSInstructionSelector::selectVST_FIFO_CONV(MachineInstr &StoreI,
                                                    MachineRegisterInfo &MRI) {
  // Operand 7 is the first component (Mantissa) of the BFP384 push
  const Register Mantissa = StoreI.getOperand(7).getReg();
  MachineInstr *MantissaDef = MRI.getVRegDef(Mantissa);

  if (!MantissaDef)
    return false;

  auto *VConvOp = dyn_cast<GIntrinsic>(MantissaDef);
  if (!VConvOp)
    return false;

  if (VConvOp->getIntrinsicID() != Intrinsic::aie2ps_v64accfloat_to_v64mx6)
    return false;

  // Verify other components come from the same VCONV and match correct outputs
  const Register SignBit = StoreI.getOperand(8).getReg();
  const Register SubTile = StoreI.getOperand(9).getReg();
  const Register Exponent = StoreI.getOperand(10).getReg();

  if (VConvOp->getOperand(0).getReg() != Mantissa)
    return false;
  if (VConvOp->getOperand(1).getReg() != SignBit)
    return false;
  if (VConvOp->getOperand(2).getReg() != SubTile)
    return false;
  if (VConvOp->getOperand(3).getReg() != Exponent)
    return false;

  // Source of intrinsic is operand 5 (4 defs + 1 ID + source)
  const Register SrcReg = VConvOp->getOperand(5).getReg();

  const Register PtrOut = StoreI.getOperand(0).getReg();
  const Register FifoOut = StoreI.getOperand(1).getReg();
  const Register AvailOut = StoreI.getOperand(2).getReg();

  const Register PtrIn = StoreI.getOperand(4).getReg();
  const Register FifoIn = StoreI.getOperand(5).getReg();
  const Register AvailIn = StoreI.getOperand(6).getReg();

  auto NewInstr = MIB.buildInstr(AIE2PS::VST_PUSH_384_CONV_mx6_fp32,
                                 {FifoOut, PtrOut, AvailOut},
                                 {FifoIn, SrcReg, PtrIn, AvailIn});
  NewInstr.cloneMemRefs(StoreI);

  makeDeadMI(*VConvOp, MRI);
  StoreI.eraseFromParent();

  return constrainSelectedInstRegOperands(*NewInstr.getInstr(), TII, TRI, RBI);
}

bool AIE2PSInstructionSelector::selectVST_FIFO(MachineInstr &I,
                                               MachineRegisterInfo &MRI) {
  const auto IntrinsicID = cast<GIntrinsic>(I).getIntrinsicID();
  MachineInstrBuilder MI;
  const Register PtrOut = I.getOperand(0).getReg();
  const Register FifoOut = I.getOperand(1).getReg();
  const Register AvailOut = I.getOperand(2).getReg();
  switch (IntrinsicID) {
  case Intrinsic::aie2ps_fifo_st_push_512: {
    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(6).getReg();
    const Register AvailIn = I.getOperand(7).getReg();
    const Register VecIn = I.getOperand(5).getReg();

    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, VecIn, PtrIn, AvailIn});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_push_BFP384: {
    // First try to match CONV combine
    if (selectVST_FIFO_CONV(I, MRI))
      return true;

    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(5).getReg();
    const Register AvailIn = I.getOperand(6).getReg();
    const Register Mantissa = I.getOperand(7).getReg();
    const Register SignBit = I.getOperand(8).getReg();
    const Register SubTile = I.getOperand(9).getReg();
    const Register Exponent = I.getOperand(10).getReg();
    // Combine into few register (384 bits)
    const Register BFP384_Reg =
        MRI.createVirtualRegister(&AIE2PS::mFEWmRegClass);
    MI = MIB.buildInstr(TargetOpcode::REG_SEQUENCE, {BFP384_Reg}, {})
             .addReg(Mantissa)
             .addImm(AIE2PS::sub_few_bfp_w)
             .addReg(SignBit)
             .addImm(AIE2PS::sub_few_bfp_f64)
             .addReg(SubTile)
             .addImm(AIE2PS::sub_few_bfp_g32)
             .addReg(Exponent)
             .addImm(AIE2PS::sub_few_bfp_e32);

    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, BFP384_Reg, PtrIn, AvailIn});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_push_BFP640: {
    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(5).getReg();
    const Register AvailIn = I.getOperand(6).getReg();
    const Register Mantissa = I.getOperand(7).getReg();
    const Register SubTile = I.getOperand(8).getReg();
    const Register Exponent = I.getOperand(9).getReg();
    // Combine into ex register (640 bits)
    const Register BFP640_Reg = buildBFP640(Mantissa, SubTile, Exponent, MRI);

    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, BFP640_Reg, PtrIn, AvailIn});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_push_BFP768: {
    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(5).getReg();
    const Register AvailIn = I.getOperand(6).getReg();
    const Register S1_MantX0 = I.getOperand(7).getReg();   // v8int32
    const Register S1_MantX1 = I.getOperand(8).getReg();   // v8int32
    const Register S1_SignF0 = I.getOperand(9).getReg();   // v2int32
    const Register S1_SignF1 = I.getOperand(10).getReg();  // v2int32
    const Register S1_ShiftG0 = I.getOperand(11).getReg(); // int32
    const Register S1_ShiftG1 = I.getOperand(12).getReg(); // int32
    const Register S1_ExpE0 = I.getOperand(13).getReg();   // int32
    const Register S1_ExpE1 = I.getOperand(14).getReg();   // int32
    const auto BFP768_Reg =
        buildBFP768(S1_MantX0, S1_SignF0, S1_ShiftG0, S1_ExpE0, S1_MantX1,
                    S1_SignF1, S1_ShiftG1, S1_ExpE1, MRI);

    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, BFP768_Reg, PtrIn, AvailIn});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_flush_conv:
  case Intrinsic::aie2ps_fifo_st_flush: {
    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(5).getReg();
    const Register AvailIn = I.getOperand(6).getReg();
    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, PtrIn, AvailIn});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_flush_1d:
  case Intrinsic::aie2ps_fifo_st_flush_1d_conv: {
    const Register PtrIn = I.getOperand(4).getReg();
    const Register FifoIn = I.getOperand(5).getReg();
    const Register AvailIn = I.getOperand(6).getReg();
    const Register OffsetReg = I.getOperand(7).getReg();
    MI = MIB.buildInstr(getStoreFifoOpcode(I), {FifoOut, PtrOut, AvailOut},
                        {FifoIn, PtrIn, AvailIn, OffsetReg});
    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_flush_2d:
  case Intrinsic::aie2ps_fifo_st_flush_2d_conv: {
    const Register CountOut1Reg = I.getOperand(3).getReg();
    const Register PtrIn = I.getOperand(5).getReg();
    const Register FifoIn = I.getOperand(6).getReg();
    const Register AvailIn = I.getOperand(7).getReg();
    const Register OffsetReg = I.getOperand(8).getReg();
    const Register SizeReg = I.getOperand(9).getReg();
    const Register CountIn1Reg = I.getOperand(10).getReg();
    const Register IncrReg = I.getOperand(11).getReg();
    const Register DReg =
        createDRegSequence(OffsetReg, IncrReg, SizeReg, CountIn1Reg, MRI);

    MI = MIB.buildInstr(getStoreFifoOpcode(I),
                        {FifoOut, PtrOut, AvailOut, CountOut1Reg},
                        {FifoIn, PtrIn, AvailIn, DReg});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
  case Intrinsic::aie2ps_fifo_st_flush_3d:
  case Intrinsic::aie2ps_fifo_st_flush_3d_conv: {
    const Register CountOut1Reg = I.getOperand(3).getReg();
    const Register CountOut2Reg = I.getOperand(4).getReg();

    const Register PtrIn = I.getOperand(6).getReg();
    const Register FifoIn = I.getOperand(7).getReg();
    const Register AvailIn = I.getOperand(8).getReg();
    const Register OffsetReg = I.getOperand(9).getReg();
    const Register Size1Reg = I.getOperand(10).getReg();
    const Register CountIn1Reg = I.getOperand(11).getReg();
    const Register Incr1Reg = I.getOperand(12).getReg();
    const Register Size2Reg = I.getOperand(13).getReg();
    const Register CountIn2Reg = I.getOperand(14).getReg();
    const Register Incr2Reg = I.getOperand(15).getReg();

    const Register DSReg =
        createDSRegSequence(OffsetReg, Incr1Reg, Incr2Reg, Size1Reg,
                            CountIn1Reg, Size2Reg, CountIn2Reg, MRI);

    MI = MIB.buildInstr(getStoreFifoOpcode(I),
                        {FifoOut, PtrOut, AvailOut, CountOut1Reg, CountOut2Reg},
                        {FifoIn, PtrIn, AvailIn, DSReg});

    MI.cloneMemRefs(I);
    I.eraseFromParent();
    return constrainSelectedInstRegOperands(*MI, TII, TRI, RBI);
  }
    return false;
  }
  return false;
}

bool AIE2PSInstructionSelector::selectCascadeStreamInsn(
    MachineInstr &I, MachineRegisterInfo &MRI, bool IsWrite) {
  const Register CascadeReg = I.getOperand(IsWrite ? 1 : 0).getReg();
  Register EnableReg = I.getOperand(I.getNumOperands() - 1).getReg();
  MachineInstrBuilder CascadeMV;
  const unsigned OpCode = TII.getOpCode(I);

  // Helper to extract ACC1024 sub-register from an ACC2048 result.
  auto ExtractACC1024 = [&]() {
    auto DestMI = MIB.buildInstr(TargetOpcode::COPY, {CascadeReg}, {})
                      .addReg(CascadeMV->getOperand(0).getReg(), 0,
                              AIE2PS::sub_1024_acc_lo);
    constrainOperandRegClass(*MF, TRI, MRI, TII, RBI, *DestMI,
                             AIE2PS::ACC1024RegClass, DestMI->getOperand(0));
  };

  if (IsWrite) {
    CascadeMV = MIB.buildInstr(OpCode, {}, {}).addReg(CascadeReg);
  } else {
    auto IntrinsicID = cast<GIntrinsic>(I).getIntrinsicID();
    switch (IntrinsicID) {
    case Intrinsic::aie2ps_scd_expand_ACC2048: {
      EnableReg = I.getOperand(I.getNumOperands() - 2).getReg();
      const Register PosReg = I.getOperand(I.getNumOperands() - 1).getReg();
      auto CopyPosReg = MIB.buildInstr(TargetOpcode::COPY,
                                       {&AIE2PS::mR31_scdRegClass}, {PosReg});
      if (!selectCopy(*CopyPosReg, MRI)) {
        return false;
      }
      CascadeMV =
          MIB.buildInstr(OpCode, {CascadeReg}, {}).addReg(CopyPosReg.getReg(0));
      break;
    }
    case Intrinsic::aie2ps_scd_expand_ACC1024: {
      EnableReg = I.getOperand(I.getNumOperands() - 2).getReg();
      const Register PosReg = I.getOperand(I.getNumOperands() - 1).getReg();
      auto CopyPosReg = MIB.buildInstr(TargetOpcode::COPY,
                                       {&AIE2PS::mR31_scdRegClass}, {PosReg});
      if (!selectCopy(*CopyPosReg, MRI)) {
        return false;
      }
      Register DstReg = MRI.createVirtualRegister(&AIE2PS::ACC2048RegClass);
      CascadeMV =
          MIB.buildInstr(OpCode, {DstReg}, {}).addReg(CopyPosReg.getReg(0));
      ExtractACC1024();
      break;
    }
    case Intrinsic::aie2ps_scd_expand_ACC2048_incr: {
      const Register R31 = I.getOperand(1).getReg();
      EnableReg = I.getOperand(I.getNumOperands() - 2).getReg();
      const Register PosPtrInReg =
          I.getOperand(I.getNumOperands() - 1).getReg();
      CascadeMV =
          MIB.buildInstr(OpCode, {CascadeReg, R31}, {}).addReg(PosPtrInReg);
      break;
    }
    case Intrinsic::aie2ps_scd_expand_ACC1024_incr: {
      const Register R31 = I.getOperand(1).getReg();
      EnableReg = I.getOperand(I.getNumOperands() - 2).getReg();
      const Register PosPtrInReg =
          I.getOperand(I.getNumOperands() - 1).getReg();
      Register DstReg = MRI.createVirtualRegister(&AIE2PS::ACC2048RegClass);
      auto CopyPosPtrInReg = MIB.buildInstr(
          TargetOpcode::COPY, {&AIE2PS::mR31_scdRegClass}, {PosPtrInReg});
      CascadeMV = MIB.buildInstr(OpCode, {DstReg, R31}, {})
                      .addReg(CopyPosPtrInReg.getReg(0));
      RBI.constrainGenericRegister(R31, AIE2PS::mR31_scdRegClass, MRI);
      ExtractACC1024();
      break;
    }
    default:
      CascadeMV = MIB.buildInstr(OpCode, {CascadeReg}, {});
      break;
    }
  }
  setUnsetCtrlRegister(MIB, *CascadeMV, MRI,
                       (IsWrite ? AIE2PS::crMCDEn : AIE2PS::crSCDEn), EnableReg,
                       1);

  I.eraseFromParent();
  return constrainSelectedInstRegOperands(*CascadeMV, TII, TRI, RBI);
}

namespace llvm {
InstructionSelector *
createAIE2PSInstructionSelector(const AIE2PSTargetMachine &TM,
                                AIE2PSSubtarget &Subtarget,
                                AIE2PSRegisterBankInfo &RBI) {
  return new AIE2PSInstructionSelector(TM, Subtarget, RBI);
}

} // end namespace llvm
